#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Generate the menu's double-resolution coverage masks from Noto Sans."""
from argparse import ArgumentParser
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

parser = ArgumentParser(description=__doc__)
parser.add_argument("regular", type=Path)
parser.add_argument("bold", type=Path)
parser.add_argument("output", type=Path)
args = parser.parse_args()
ranges = [*range(32, 127), *range(160, 256)]
out = [
    "// SPDX-License-Identifier: OFL-1.1",
    "// Generated by scripts/generate-menu-font.py from Noto Sans. See resources/menu-font-license.txt.",
    "#pragma once",
    "#include <cstdint>",
    "namespace menu_font {",
    "struct Glyph { uint16_t offset; int8_t x, y; uint8_t width, height, advance; };",
]
for name, source, size, baseline in (("body", args.regular, 20, 20), ("title", args.bold, 23, 22)):
    font = ImageFont.truetype(str(source), size)
    glyphs, masks = [], []
    for code in ranges:
        char = chr(code)
        x1, y1, x2, y2 = font.getbbox(char, anchor="ls")
        width, height = x2 - x1, y2 - y1
        offset = len(masks)
        if width and height:
            bitmap = Image.new("L", (width, height))
            ImageDraw.Draw(bitmap).text((-x1, -y1), char, fill=255, font=font, anchor="ls")
            pixels = [(value + 8) // 17 for value in bitmap.tobytes()]
            pixels += [0] * (len(pixels) % 2)
            masks.extend((pixels[i] << 4) | pixels[i + 1] for i in range(0, len(pixels), 2))
        glyphs.append((offset, x1, y1 + baseline, width, height, round(font.getlength(char))))
    assert len(masks) < 65536
    out.extend([f"inline constexpr Glyph {name}_glyphs[] = {{",
                *(f"    {{{', '.join(map(str, item))}}}," for item in glyphs), "};"])
    out.append(f"inline constexpr uint8_t {name}_masks[] = {{")
    for i in range(0, len(masks), 24):
        out.append("    " + ", ".join(f"0x{value:02x}" for value in masks[i:i+24]) + ",")
    out.append("};")
out.append("}")
args.output.write_text("\n".join(out) + "\n")
